// mongo-init.js

// Switch to the admin database
const adminDb = db.getSiblingDB("admin");

// Get username and password from environment variables
const username = process.env.MONGO_INITDB_USERNAME;
const password = process.env.MONGO_INITDB_PASSWORD;
const database = process.env.MONGO_INITDB_DATABASE;

// Create the user
if (adminDb.getUser(username) === null) {
  adminDb.createUser({
    user: username,
    pwd: password,
    roles: [{ role: "readWrite", db: database }],
  });
}

{
  auto_https off
  admin off
  servers {
    trusted_proxies static private_ranges
  }
}
:8080 {
  handle /v1/realtime* {
    reverse_proxy appwrite-realtime:80
  }
  handle /v1* {
    reverse_proxy appwrite:80
  }
  handle {
    reverse_proxy appwrite-console:3000
  }
}
